<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Percent/distributor_agent')}">分销员/代理商设置</a>					<a href="{pigcms{:U('User/agent_log')}" class="on">代理商列表</a>					<a href="{pigcms{:U('User/agent_next_log')}&action=agent"  <if condition="$_GET['action'] eq 'agent'">class="on"</if>>代理商下级</a>					<a href="{pigcms{:U('User/agent_next_log')}&action=distributor" <if condition="$_GET['action'] eq 'distributor'">class="on"</if>>分销员下级</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('User/agent_log')}" method="get">							<input type="hidden" name="c" value="User"/>							<input type="hidden" name="a" value="agent_log"/>							筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="uid" <if condition="$_GET['searchtype'] eq 'uid'">selected="selected"</if>>用户ID</option>								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>昵称</option>								<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>						代理商佣金总额：{pigcms{$all_spread_money|floatval}{pigcms{$config['Currency_txt']}						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th><a href="{pigcms{:U('User/index',array('sort'=>'uid'))}" style="color:blue;">ID</a></th>								<th>昵称</th>								<th>手机号</th>								<th class="textcenter">推广佣金</th>								<th class="textcenter">推广商家</th>								<th class="textcenter">佣金记录</th>							</tr>						</thead>						<tbody>							<if condition="is_array($agent_list)">								<volist name="agent_list" id="vo">									<tr>										<td>{pigcms{$vo.uid}</td>										<td>{pigcms{$vo.nickname}</td>										<td>{pigcms{$vo.phone}</td>										<td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo.spread_money|floatval=###}</td>										<td class="textcenter"><a href="{pigcms{:U('User/agent_merchant_list')}&uid={pigcms{$vo.uid}" >查看商家</a>										&nbsp;&nbsp;共{pigcms{$vo.counts}个										</td>										<td class="textcenter">										<a href="{pigcms{:U('User/agent_money_list')}&uid={pigcms{$vo.uid}" >查看佣金</a>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="11">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="11">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		 var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('User/export')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>